import 'dart:async';

import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_app/core/providers/navigation_provider.dart';
import 'package:ukcheckpoints_app/core/services/realtime_service.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/auth/providers/auth_controller.dart';
import 'package:ukcheckpoints_app/features/checkpoints/screens/checkpoint_list_screen.dart';
import 'package:ukcheckpoints_app/features/map/screens/map_screen.dart';
import 'package:ukcheckpoints_app/features/profile/screens/profile_screen.dart';

class MainWrapper extends ConsumerStatefulWidget {
  const MainWrapper({super.key});

  @override
  ConsumerState<MainWrapper> createState() => _MainWrapperState();
}

class _MainWrapperState extends ConsumerState<MainWrapper> {
  static const _screens = <Widget>[
    MapScreen(),
    CheckpointListScreen(),
    ProfileScreen(),
  ];

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final user = ref.read(authControllerProvider).value;
      if (user != null) {
        unawaited(ref.read(realtimeServiceProvider).connect());
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    final index = ref.watch(bottomNavIndexProvider);

    return Scaffold(
      body: IndexedStack(index: index, children: _screens),
      bottomNavigationBar: Container(
        decoration: const BoxDecoration(
          color: ThemeColors.bgRaised,
          border: Border(
            top: BorderSide(color: ThemeColors.border, width: 0.5),
          ),
        ),
        child: SafeArea(
          child: SizedBox(
            height: 54,
            child: Row(
              children: [
                _NavItem(
                  icon: CupertinoIcons.map,
                  activeIcon: CupertinoIcons.map_fill,
                  label: 'Map',
                  index: 0,
                  currentIndex: index,
                  onTap: () {
                    ref.read(bottomNavIndexProvider.notifier).state = 0;
                  },
                ),
                _NavItem(
                  icon: CupertinoIcons.shield,
                  activeIcon: CupertinoIcons.shield_fill,
                  label: 'Checkpoints',
                  index: 1,
                  currentIndex: index,
                  onTap: () {
                    ref.read(bottomNavIndexProvider.notifier).state = 1;
                  },
                ),
                _NavItem(
                  icon: CupertinoIcons.person,
                  activeIcon: CupertinoIcons.person_fill,
                  label: 'Profile',
                  index: 2,
                  currentIndex: index,
                  onTap: () {
                    ref.read(bottomNavIndexProvider.notifier).state = 2;
                  },
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _NavItem extends StatelessWidget {
  final IconData icon;
  final IconData activeIcon;
  final String label;
  final int index;
  final int currentIndex;
  final VoidCallback onTap;

  const _NavItem({
    required this.icon,
    required this.activeIcon,
    required this.label,
    required this.index,
    required this.currentIndex,
    required this.onTap,
  });

  @override
  Widget build(BuildContext context) {
    final isActive = index == currentIndex;
    return Expanded(
      child: GestureDetector(
        onTap: onTap,
        behavior: HitTestBehavior.opaque,
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(
              isActive ? activeIcon : icon,
              size: 22,
              color: isActive ? ThemeColors.accent : ThemeColors.stone500,
            ),
            const SizedBox(height: 4),
            Text(
              label,
              style: TextStyle(
                fontSize: 10,
                fontWeight: isActive ? FontWeight.w600 : FontWeight.w500,
                color: isActive ? ThemeColors.accent : ThemeColors.stone500,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

