3	import 'package:flutter_riverpod/flutter_riverpod.dart';
4	import 'package:here_sdk/core.dart';
5	import 'package:here_sdk/core.engine.dart';
6	import 'package:here_sdk/gestures.dart';
7	import 'package:here_sdk/mapview.dart';
8	import 'package:here_sdk/prefetcher.dart';
9	import 'package:riverpod_annotation/riverpod_annotation.dart';
10	import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
11	
12	import 'package:ukcheckpoints_app/core/utils/logger.dart';
13	import 'package:ukcheckpoints_app/features/map/data/map_preferences_repository.dart';
14	
15	part 'map_controller.g.dart';
16	
17	final mapBearingProvider = StateProvider<double>((ref) => 0.0);
18	
19	final currentMapSchemeProvider = StateProvider<MapScheme>(
20	  (ref) => MapScheme.normalDay,
21	);
22	
23	final isTrafficEnabledProvider = StateProvider<bool>((ref) => false);
24	
25	final isPublicTransitEnabledProvider = StateProvider<bool>((ref) => false);
26	
27	@Riverpod(keepAlive: true)
28	class MapController extends _$MapController {
29	  LocationIndicator? _locationIndicator;
30	  GeoCoordinates? _lastLocation;
31	
32	  // Keyed by checkpointId for O(1) diffing.
33	  final Map<String, MapMarker> _markerById = {};
34	
35	  PolygonPrefetcher? _prefetcher;
36	  bool _hasPrefetched = false;
37	
38	  @override
39	  HereMapController? build() {
40	    ref.onDispose(() {
41	      _locationIndicator = null;
42	      _markerById.clear();
43	    });
44	    return null;
45	  }
46	
47	  void setController(
48	    HereMapController controller,
49	    void Function(String) onCheckpointTap,
50	  ) {
51	    state = controller;
52	    _setupLocationIndicator(controller);
53	    _setupGestureListeners(controller, onCheckpointTap);
54	    unawaited(_loadAndApplyPreferences());
55	  }
56	
57	  Future<void> _loadAndApplyPreferences() async {
58	    final prefs = ref.read(mapPreferencesRepositoryProvider);
59	    final schemeName = await prefs.getMapScheme();
60	    final trafficOn = await prefs.isTrafficEnabled();
61	    final transitOn = await prefs.isPublicTransitEnabled();
62	
63	    final scheme = MapScheme.values.firstWhere(
64	      (s) => s.name == schemeName,
65	      orElse: () => MapScheme.normalDay,
66	    );
67	
68	    ref.read(isTrafficEnabledProvider.notifier).state = trafficOn;
69	    ref.read(isPublicTransitEnabledProvider.notifier).state = transitOn;
70	
71	    if (state != null) {
72	      setMapScheme(scheme, refocus: true);
73	    }
74	  }
75	
76	  void _setupGestureListeners(
77	    HereMapController controller,
78	    void Function(String) onCheckpointTap,
79	  ) {
80	    controller.gestures.tapListener = TapListener((Point2D point) {
81	      final current = state;
82	      if (current == null) return;
83	
84	      current.pick(
85	        MapSceneMapPickFilter([MapSceneMapPickFilterContentType.mapItems]),
86	        Rectangle2D(point, Size2D(40, 40)),
87	        (MapPickResult? result) {
88	          final marker = result?.mapItems?.markers.firstOrNull;
89	          if (marker == null) return;
90	          final id = marker.metadata?.getString('checkpointId');
91	          if (id != null) onCheckpointTap(id);
92	        },
93	      );
94	    });
95	  }
96	
97	  void _setupLocationIndicator(HereMapController controller) {
98	    _locationIndicator = LocationIndicator.withMapView(controller)
99	      ..locationIndicatorStyle = LocationIndicatorIndicatorStyle.pedestrian
100	      ..enable(controller);
101	  }
102	
103	  void updateLocation(GeoCoordinates coordinates) {
104	    final isFirstLocation = _lastLocation == null;
105	    _lastLocation = coordinates;
106	    _locationIndicator?.updateLocation(Location.withCoordinates(coordinates));
107	
