import 'dart:math';

import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:geolocator/geolocator.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';

const double _kNearbyThresholdMeters = 200;

class NearbyCheckpointState {
  final Checkpoint checkpoint;
  final double distanceMeters;

  const NearbyCheckpointState({
    required this.checkpoint,
    required this.distanceMeters,
  });
}

final nearbyCheckpointProvider =
    StateNotifierProvider<NearbyCheckpointNotifier, NearbyCheckpointState?>(
  (ref) => NearbyCheckpointNotifier(ref),
);

class NearbyCheckpointNotifier extends StateNotifier<NearbyCheckpointState?> {
  final Ref _ref;
  final Set<String> _notifiedIds = {};

  NearbyCheckpointNotifier(this._ref) : super(null) {
    _ref.listen(userLocationStreamProvider, (previous, next) {
      final position = next.value;
      if (position != null) _checkProximity(position);
    });
  }

  void _checkProximity(Position position) {
    final checkpointState = _ref.read(checkpointNotifierProvider).value;
    if (checkpointState == null) return;

    final lat = position.latitude;
    final lng = position.longitude;

    Checkpoint? closest;
    double closestDist = double.infinity;

    for (final cp in checkpointState.checkpoints) {
      if (_notifiedIds.contains(cp.id)) continue;

      final dist = _haversineMeters(
        lat,
        lng,
        cp.latitude.toDouble(),
        cp.longitude.toDouble(),
      );

      if (dist <= _kNearbyThresholdMeters && dist < closestDist) {
        closest = cp;
        closestDist = dist;
      }
    }

    if (closest != null) {
      _notifiedIds.add(closest.id);
      state = NearbyCheckpointState(
        checkpoint: closest,
        distanceMeters: closestDist,
      );
    }
  }

  void dismiss() {
    state = null;
  }
}

double _haversineMeters(
  double lat1,
  double lng1,
  double lat2,
  double lng2,
) {
  const p = 0.017453292519943295;
  final a =
      0.5 -
      cos((lat1 - lat2) * p) / 2 +
      cos(lat2 * p) *
          cos(lat1 * p) *
          (1 - cos((lng1 - lng2) * p)) /
          2;
  return 12742 * asin(a) * 1000;
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';

class MapSpeedOverlay extends ConsumerWidget {
  const MapSpeedOverlay({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final location = ref.watch(userLocationStreamProvider).value;

    if (location == null) return const SizedBox.shrink();

    final speedMs = location.speed;
    final speedMph = speedMs * 2.23694;

    if (speedMph < 3.0) return const SizedBox.shrink();

    return Container(
      decoration: BoxDecoration(
        color: ThemeColors.bgRaised,
        borderRadius: ThemeRadius.brFull,
        boxShadow: ThemeShadows.md,
        border: Border.all(color: ThemeColors.border),
      ),
      child: Padding(
        padding: const EdgeInsets.symmetric(
          horizontal: 16,
          vertical: 10,
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              speedMph.toStringAsFixed(0),
              style: const TextStyle(
                fontFamily: ThemeFonts.ui,
                fontSize: 22,
                fontWeight: FontWeight.w600,
                height: 1,
                color: ThemeColors.accent,
              ),
            ),
            const SizedBox(width: 4),
            const Text(
              'mph',
              style: TextStyle(
                fontFamily: ThemeFonts.ui,
                fontSize: 11,
                fontWeight: FontWeight.w500,
                height: 1,
                color: ThemeColors.textSecondary,
              ),
            ),
          ],
        ),
      ),
    );
  }
}

