import 'package:here_sdk/core.dart';
import 'package:here_sdk/core.engine.dart';
import 'package:here_sdk/core.errors.dart';
import 'package:sentry_flutter/sentry_flutter.dart';
import 'package:ukcheckpoints_app/core/api/deep_link_provider.dart';
import 'package:ukcheckpoints_app/core/providers/location_provider.dart';
import 'package:ukcheckpoints_app/core/router/router.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/auth/providers/auth_controller.dart';

Future<void> main() async {
  final widgetsBinding = SentryWidgetsFlutterBinding.ensureInitialized();
  FlutterNativeSplash.preserve(widgetsBinding: widgetsBinding);

  SdkContext.init(IsolateOrigin.main);

  const accessKeyId = String.fromEnvironment(
    'HERESDK_ACCESS_KEY_ID',
    defaultValue: 'YOUR_KEY_ID',
  );
  const accessKeySecret = String.fromEnvironment(
    'HERESDK_ACCESS_KEY_SECRET',
    defaultValue: 'YOUR_SECRET',
  );

  if (accessKeyId.isEmpty || accessKeySecret.isEmpty) {
    throw Exception(
      "HERE SDK credentials are missing. Check your --dart-define-from-file setup.",
    );
  }

  final sdkOptions = SDKOptions.withAuthenticationMode(
    AuthenticationMode.withKeySecret(accessKeyId, accessKeySecret),
  );

  // Only enable layers this app actually uses. Disabling offline search,
  // offline routing, truck, 3D landmarks, and terrain shrinks every OCM tile
  // download and keeps the cache smaller, which directly reduces tile-pop-in.
  sdkOptions.layerConfiguration = LayerConfiguration([
    LayerConfigurationFeature.rendering,
    LayerConfigurationFeature.detailRendering,
    LayerConfigurationFeature.navigation,
  ]);

  try {
    await SDKNativeEngine.makeSharedInstance(sdkOptions);
  } on InstantiationException {
    throw Exception('Failed to initialize HERE SDK.');
  }

  await SentryFlutter.init(
    (options) {
      options.dsn =
          'https://0d481c7048c44c2881f90115f0f802ad@telemetry.ukcheckpoints.info/4';
      options.tracesSampleRate = 1.0;
      options.reportPackages = false;
      options.attachScreenshot = false;
    },
    appRunner:
        () => runApp(
          ProviderScope(
            child: DefaultAssetBundle(
              bundle: SentryAssetBundle(),
              child: const UKCheckpointsApp(),
            ),
          ),
        ),
  );
}

class UKCheckpointsApp extends ConsumerStatefulWidget {
  const UKCheckpointsApp({super.key});

  @override
  ConsumerState<UKCheckpointsApp> createState() => _UKCheckpointsAppState();
}

class _UKCheckpointsAppState extends ConsumerState<UKCheckpointsApp> {
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      ref.read(locationControllerProvider.notifier).checkStatus();
    });
  }

  @override
  Widget build(BuildContext context) {
    final router = ref.watch(routerProvider);

    ref.listen<AsyncValue<Uri>>(deepLinkProvider, (previous, next) {
      final uri = next.value;
      if (uri != null) {
        router.push(uri.path + (uri.hasQuery ? '?${uri.query}' : ''));
      }
    });

    ref.listen(authControllerProvider, (previous, next) {
      if (!next.isLoading) {
        FlutterNativeSplash.remove();
      }
    });

    return MaterialApp.router(
      debugShowCheckedModeBanner: false,
      title: "UKcheckpoints",
      theme: AppTheme.light,
      routerConfig: router,
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/nearby_checkpoint_provider.dart';

class NearbyCheckpointPopup extends ConsumerWidget {
  const NearbyCheckpointPopup({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final nearby = ref.watch(nearbyCheckpointProvider);
    if (nearby == null) return const SizedBox.shrink();

    final cp = nearby.checkpoint;
    final status = cp.contributions.isNotEmpty
        ? cp.contributions.first.status
        : ContributionStatusEnum.UNKNOWN;

    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: ThemeSpacing.sp4),
      child: Container(
        padding: const EdgeInsets.all(ThemeSpacing.sp4),
        decoration: BoxDecoration(
          color: ThemeColors.bgRaised,
          borderRadius: ThemeRadius.brLg,
          border: Border.all(color: ThemeColors.border),
          boxShadow: ThemeShadows.lg,
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              children: [
                Container(
                  width: 8,
                  height: 8,
                  decoration: BoxDecoration(
                    color: _statusColor(status),
                    shape: BoxShape.circle,
                  ),
                ),
                const SizedBox(width: ThemeSpacing.sp2),
                const Text(
                  'Nearby Checkpoint',
                  style: TextStyle(
                    fontFamily: ThemeFonts.ui,
                    fontSize: 11,
                    fontWeight: FontWeight.w500,
                    letterSpacing: 0.5,
                    color: ThemeColors.textTertiary,
                  ),
                ),
                const Spacer(),
                SizedBox(
                  width: 28,
                  height: 28,
                  child: IconButton(
                    icon: const Icon(Icons.close, size: 16),
                    onPressed: () {
                      ref.read(nearbyCheckpointProvider.notifier).dismiss();
                    },
                    splashRadius: 14,
                    color: ThemeColors.textTertiary,
                  ),
                ),
              ],
            ),
            const SizedBox(height: ThemeSpacing.sp2),
            Text(
              cp.name,
              style: ThemeText.headline,
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
            ),
            const SizedBox(height: 2),
            Text(
              'Status: ${status.name}',
              style: ThemeText.subheadline,
            ),
            const SizedBox(height: ThemeSpacing.sp3),
            Text(
              'Confirm status if possible',
              style: ThemeText.footnote,
            ),
            const SizedBox(height: ThemeSpacing.sp3),
            Row(
              children: [
                Expanded(
                  child: SizedBox(
                    height: 44,
                    child: ElevatedButton(
                      onPressed: () {
                        ref
                            .read(checkpointNotifierProvider.notifier)
                            .contribute(cp.id, ContributionStatusEnum.ACTIVE);
                        ref
                            .read(nearbyCheckpointProvider.notifier)
                            .dismiss();
                      },
                      style: ElevatedButton.styleFrom(
                        backgroundColor: ThemeColors.danger,
                        foregroundColor: Colors.white,
                        elevation: 0,
                        shape: RoundedRectangleBorder(
                          borderRadius: ThemeRadius.brMd,
                        ),
                      ),
                      child: const Text('Active'),
                    ),
                  ),
                ),
                const SizedBox(width: ThemeSpacing.sp2),
                Expanded(
                  child: SizedBox(
                    height: 44,
                    child: OutlinedButton(
                      onPressed: () {
                        ref
                            .read(checkpointNotifierProvider.notifier)
                            .contribute(
                              cp.id,
                              ContributionStatusEnum.INACTIVE,
                            );
                        ref
                            .read(nearbyCheckpointProvider.notifier)
                            .dismiss();
                      },
                      style: OutlinedButton.styleFrom(
                        foregroundColor: ThemeColors.success,
                        side: const BorderSide(color: ThemeColors.success),
                        shape: RoundedRectangleBorder(
                          borderRadius: ThemeRadius.brMd,
                        ),
                      ),
                      child: const Text('Clear'),
                    ),
                  ),
                ),
                const SizedBox(width: ThemeSpacing.sp2),
                Expanded(
                  child: SizedBox(
                    height: 44,
                    child: TextButton(
                      onPressed: () {
                        ref
                            .read(nearbyCheckpointProvider.notifier)
                            .dismiss();
                      },
                      child: const Text('Unknown'),
                    ),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Color _statusColor(ContributionStatusEnum? status) {
    return switch (status) {
      ContributionStatusEnum.ACTIVE => ThemeColors.danger,
      ContributionStatusEnum.INACTIVE => ThemeColors.success,
      ContributionStatusEnum.POLICE_ALERT => const Color(0xFFFF9500),
      _ => ThemeColors.stone400,
    };
  }
}

