    final toAdd = <MapMarker>[];
    for (final checkpoint in checkpoints) {
      final existing = _markerById[checkpoint.id];
      if (existing != null) {
        final currentStatus = existing.metadata?.getString('status');
        if (currentStatus == _statusFor(checkpoint).name) continue;
        // Status changed — replace.
        controller.mapScene.removeMapMarker(existing);
        _markerById.remove(checkpoint.id);
      }
      final marker = _buildMarker(checkpoint, icons);
      toAdd.add(marker);
      _markerById[checkpoint.id] = marker;
    }
    if (toAdd.isNotEmpty) {
      controller.mapScene.addMapMarkers(toAdd);
    }
  }

  void setMapScheme(MapScheme scheme, {bool refocus = false}) {
    ref.read(currentMapSchemeProvider.notifier).state = scheme;

    unawaited(
      ref.read(mapPreferencesRepositoryProvider).setMapScheme(scheme.name),
    );

    final coordinates = refocus ? _lastLocation : null;

    final options = MapSceneLoadOptionsBuilder().withMapScheme(scheme).build();
    state?.mapScene.loadScene(options, (MapError? error) {
      if (error != null) {
        AppLogger.error(
          'Map scene load failed',
          error: error,
          stackTrace: StackTrace.current,
        );
        return;
      }
      _reapplyFeatures();
      if (coordinates != null) {
        _animateTo(coordinates);
      }
    });
  }

  void _reapplyFeatures() {
    final controller = state;
    if (controller == null) return;

    final scheme = ref.read(currentMapSchemeProvider);
    final trafficOn = ref.read(isTrafficEnabledProvider);
    final transitOn = ref.read(isPublicTransitEnabledProvider);

    if (scheme == MapScheme.satellite) return;

    if (trafficOn) {
      controller.mapScene.enableFeatures({
        MapFeatures.trafficFlow: MapFeatureModes.trafficFlowWithFreeFlow,
        MapFeatures.trafficIncidents: MapFeatureModes.trafficIncidentsAll,
      });
    }
    if (transitOn) {
      controller.mapScene.enableFeatures({
        MapFeatures.publicTransit: MapFeatureModes.publicTransitAll,
      });
    }
  }

  void toggleTrafficFlow() {
    final newValue = !ref.read(isTrafficEnabledProvider);
    ref.read(isTrafficEnabledProvider.notifier).state = newValue;

    unawaited(
      ref.read(mapPreferencesRepositoryProvider).setTrafficEnabled(newValue),
    );

    final controller = state;
    if (controller == null) return;

    if (ref.read(currentMapSchemeProvider) == MapScheme.satellite) return;

    if (newValue) {
      controller.mapScene.enableFeatures({
        MapFeatures.trafficFlow: MapFeatureModes.trafficFlowWithFreeFlow,
        MapFeatures.trafficIncidents: MapFeatureModes.trafficIncidentsAll,
      });
    } else {
      controller.mapScene.disableFeatures([
        MapFeatures.trafficFlow,
        MapFeatures.trafficIncidents,
      ]);
    }
  }

  void togglePublicTransit() {
    final newValue = !ref.read(isPublicTransitEnabledProvider);
    ref.read(isPublicTransitEnabledProvider.notifier).state = newValue;

    unawaited(
      ref
          .read(mapPreferencesRepositoryProvider)
          .setPublicTransitEnabled(newValue),
    );

    final controller = state;
    if (controller == null) return;

    if (ref.read(currentMapSchemeProvider) == MapScheme.satellite) return;

    if (newValue) {
      controller.mapScene.enableFeatures({
        MapFeatures.publicTransit: MapFeatureModes.publicTransitAll,
      });
    } else {
      controller.mapScene.disableFeatures([MapFeatures.publicTransit]);
    }
  }

  void focusOnCheckpoint(Checkpoint checkpoint) {
    final controller = state;
    if (controller == null) return;

    final animation = MapCameraAnimationFactory.flyToWithZoom(
      GeoCoordinatesUpdate(
        checkpoint.latitude.toDouble(),
        checkpoint.longitude.toDouble(),
      ),
      MapMeasure(MapMeasureKind.distanceInMeters, 500),
      0,
      const Duration(milliseconds: 800),
    );
    controller.camera.startAnimation(animation);
  }

}

import 'dart:convert';
import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:path_provider/path_provider.dart';

class MapPreferencesService {
  static const _defaults = {
    'mapScheme': 'normalDay',
    'trafficEnabled': false,
    'publicTransitEnabled': false,
    'safetyCamerasEnabled': false,
    'trafficLightsEnabled': false,
    'congestionZonesEnabled': false,
    'roadExitLabelsEnabled': false,
  };

  Map<String, dynamic> _prefs = Map.of(_defaults);
  bool _loaded = false;

  Future<String> get _path async {
    final dir = await getApplicationDocumentsDirectory();
    return '${dir.path}/map_preferences.json';
  }

  Future<void> _ensureLoaded() async {
    if (_loaded) return;
    _loaded = true;
    try {
      final file = File(await _path);
      if (await file.exists()) {
        final content = await file.readAsString();
        final json = jsonDecode(content) as Map<String, dynamic>;
        _prefs = Map.of(_defaults);
        for (final key in _defaults.keys) {
          if (json.containsKey(key)) {
            _prefs[key] = json[key];
          }
        }
      }
    } catch (e, st) {
      debugPrint('[MapPreferencesService] load error: $e\n$st');
      _prefs = Map.of(_defaults);
    }
  }

  Future<void> _save() async {
    final file = File(await _path);
    await file.writeAsString(jsonEncode(_prefs));
  }

  // ── Getters ──────────────────────────────────────────────────

  Future<String> getMapScheme() async {
    await _ensureLoaded();
    return _prefs['mapScheme'] as String;
  }

  Future<bool> isTrafficEnabled() async {
    await _ensureLoaded();
    return _prefs['trafficEnabled'] as bool;
  }

  Future<bool> isPublicTransitEnabled() async {
    await _ensureLoaded();
    return _prefs['publicTransitEnabled'] as bool;
  }

  Future<bool> isSafetyCamerasEnabled() async {
    await _ensureLoaded();
    return _prefs['safetyCamerasEnabled'] as bool;
  }

  Future<bool> isTrafficLightsEnabled() async {
    await _ensureLoaded();
    return _prefs['trafficLightsEnabled'] as bool;
  }

  Future<bool> isCongestionZonesEnabled() async {
    await _ensureLoaded();
    return _prefs['congestionZonesEnabled'] as bool;
  }

  Future<bool> isRoadExitLabelsEnabled() async {
    await _ensureLoaded();
    return _prefs['roadExitLabelsEnabled'] as bool;
  }

  // ── Setters ──────────────────────────────────────────────────

  Future<void> setMapScheme(String scheme) async {
    await _ensureLoaded();
    _prefs['mapScheme'] = scheme;
    await _save();
  }

  Future<void> setTrafficEnabled(bool enabled) async {
    await _ensureLoaded();
    _prefs['trafficEnabled'] = enabled;
    await _save();
  }

  Future<void> setPublicTransitEnabled(bool enabled) async {
    await _ensureLoaded();
    _prefs['publicTransitEnabled'] = enabled;
    await _save();
  }

  Future<void> setSafetyCamerasEnabled(bool enabled) async {
    await _ensureLoaded();
    _prefs['safetyCamerasEnabled'] = enabled;
    await _save();
  }

  Future<void> setTrafficLightsEnabled(bool enabled) async {
    await _ensureLoaded();
    _prefs['trafficLightsEnabled'] = enabled;
    await _save();
  }

  Future<void> setCongestionZonesEnabled(bool enabled) async {
    await _ensureLoaded();
    _prefs['congestionZonesEnabled'] = enabled;
    await _save();
  }

  Future<void> setRoadExitLabelsEnabled(bool enabled) async {
    await _ensureLoaded();
    _prefs['roadExitLabelsEnabled'] = enabled;
    await _save();
  }
}

