import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/checkpoints/domain/checkpoint_error.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_empty_view.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_error_view.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_filter_bar.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_list_content.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_search_header.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_shimmer_widget.dart';

class CheckpointListScreen extends ConsumerWidget {
  const CheckpointListScreen({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final theme = Theme.of(context);
    final filteredAsync = ref.watch(filteredCheckpointsProvider);
    final searchQuery = ref.watch(checkpointSearchProvider);
    final location = ref.watch(userLocationStreamProvider).value;
    final isSyncing = filteredAsync.value?.isSyncing ?? false;

    return Scaffold(
      backgroundColor: theme.scaffoldBackgroundColor,
      body: SafeArea(
        bottom: false,
        child: RefreshIndicator(
          onRefresh: () {
            return ref.read(checkpointNotifierProvider.notifier).refresh();
          },
          displacement: ThemeSpacing.sp8,
          color: ThemeColors.accent,
          backgroundColor: ThemeColors.bgRaised,
          strokeWidth: 2,
          child: CustomScrollView(
            physics: const AlwaysScrollableScrollPhysics(),
            slivers: [
              SliverAppBar(
                floating: true,
                snap: true,
                backgroundColor: theme.scaffoldBackgroundColor,
                surfaceTintColor: Colors.transparent,
                elevation: 0,
                centerTitle: false,
                toolbarHeight: 72,
                title: Row(
                  children: [
                    Expanded(
                      child: Text(
                        'Checkpoints',
                        style: theme.textTheme.displayMedium?.copyWith(
                          fontSize: 28,
                          fontWeight: FontWeight.w900,
                          letterSpacing: -1.2,
                          color: ThemeColors.textPrimary,
                        ),
                      ),
                    ),
                    if (isSyncing)
                      const Padding(
                        padding: EdgeInsets.only(right: ThemeSpacing.sp3),
                        child: SizedBox(
                          width: 14,
                          height: 14,
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            color: ThemeColors.accent,
                          ),
                        ),
                      ),
                    _CountBadge(count: filteredAsync.value?.total ?? 0),
                  ],
                ),
                bottom: const PreferredSize(
                  preferredSize: Size.fromHeight(104),
                  child: Column(
                    children: [
                      Padding(
                        padding: EdgeInsets.symmetric(
                          horizontal: ThemeSpacing.sp4,
                        ),
                        child: CheckpointSearchHeader(),
                      ),
                      CheckpointFilterBar(),
                      SizedBox(height: ThemeSpacing.sp2),
                    ],
                  ),
                ),
              ),
              filteredAsync.when(
                loading: () => const CheckpointShimmer(),
                error: (err, _) {
                  final message = err is CheckpointError
                      ? err.message
                      : err.toString();
                  return CheckpointErrorView(message: message);
                },
                data: (state) {
                  if (state.checkpoints.isEmpty) {
                    return CheckpointEmptyView(query: searchQuery);
                  }

                  return CheckpointListContent(
                    state: state,
                    searchQuery: searchQuery,
                    userLat: location?.latitude,
                    userLng: location?.longitude,
                  );
                },
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _CountBadge extends StatelessWidget {
  final int count;

  const _CountBadge({required this.count});

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
      decoration: BoxDecoration(
        color: ThemeColors.stone200,
        borderRadius: ThemeRadius.brFull,
      ),
      child: Text(
        count.toString(),
        style: const TextStyle(
          color: ThemeColors.textPrimary,
          fontSize: 12,
          fontWeight: FontWeight.w900,
          fontFamily: ThemeFonts.ui,
        ),
      ),
    );
  }
}

import 'dart:async';

import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/checkpoints/widgets/checkpoint_action_sheet_widget.dart';

class CheckpointCard extends StatelessWidget {
  final Checkpoint checkpoint;

  const CheckpointCard({required this.checkpoint, super.key});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final textTheme = theme.textTheme;

    final latestStatus =
        checkpoint.contributions.isNotEmpty
            ? checkpoint.contributions.first.status
            : null;

    return RepaintBoundary(
      child: Container(
        margin: const EdgeInsets.only(bottom: ThemeSpacing.sp3),
        decoration: BoxDecoration(
          color: ThemeColors.bgRaised,
          borderRadius: ThemeRadius.brLg,
          border: Border.all(color: ThemeColors.border),
          boxShadow: const [
            BoxShadow(
              color: Color(0x03000000),
              blurRadius: 10,
              offset: Offset(0, 4),
            ),
          ],
        ),
        child: ClipRRect(
          borderRadius: ThemeRadius.brLg,
          child: Material(
            color: Colors.transparent,
            child: InkWell(
              onTap: () {
                unawaited(showModalBottomSheet(
                  context: context,
                  isScrollControlled: true,
                  backgroundColor: Colors.transparent,
                  builder:
                      (context) =>
                          CheckpointActionSheet(checkpoint: checkpoint),
                ));
              },
              child: Padding(
                padding: const EdgeInsets.all(ThemeSpacing.sp4),
                child: Row(
                  children: [
                    _StatusIndicator(status: latestStatus),
                    const SizedBox(width: ThemeSpacing.sp4),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            checkpoint.name,
                            style: textTheme.titleMedium?.copyWith(
                              fontWeight: FontWeight.w600,
                              color: ThemeColors.textPrimary,
                              fontSize: 15,
                              letterSpacing: -0.3,
                            ),
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                          ),
                          const SizedBox(height: 2),
                          Text(
                            '${checkpoint.latitude.toStringAsFixed(4)}, ${checkpoint.longitude.toStringAsFixed(4)}',
                            style: const TextStyle(
                              fontFamily: 'Monospace',
                              fontSize: 11,
                              fontWeight: FontWeight.w500,
                              color: ThemeColors.textTertiary,
                            ),
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(width: ThemeSpacing.sp3),
                    Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          DateFormat(
                            'HH:mm',
                          ).format(checkpoint.createdAt.toLocal()),
                          style: textTheme.labelSmall?.copyWith(
                            fontSize: 11,
                            fontWeight: FontWeight.w600,
                            color: ThemeColors.textTertiary,
                          ),
                        ),
                        const SizedBox(width: ThemeSpacing.sp2),
                        const Icon(
                          CupertinoIcons.chevron_right,
                          size: 12,
                          color: ThemeColors.borderStrong,
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _StatusIndicator extends StatelessWidget {
  final ContributionStatusEnum? status;

  const _StatusIndicator({required this.status});

  @override
  Widget build(BuildContext context) {
    final (Color color, IconData icon) = switch (status) {
      ContributionStatusEnum.ACTIVE => (
        ThemeColors.danger,
        CupertinoIcons.dot_radiowaves_right,
      ),
      ContributionStatusEnum.INACTIVE => (
        const Color(0xFF34C759),
        CupertinoIcons.checkmark_shield_fill,
      ),
      ContributionStatusEnum.POLICE_ALERT => (
        const Color(0xFFFF9500),
        CupertinoIcons.exclamationmark_triangle_fill,
      ),
      _ => (ThemeColors.stone300, CupertinoIcons.question_circle_fill),
    };

    return Container(
      width: 40,
      height: 40,
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.06),
        shape: BoxShape.circle,
      ),
      child: Center(child: Icon(icon, color: color, size: 18)),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';
import 'package:ukcheckpoints_app/features/checkpoints/providers/checkpoint_provider.dart';

class CheckpointFilterBar extends ConsumerWidget {
  const CheckpointFilterBar({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final activeFilter = ref.watch(checkpointStatusFilterProvider);
    return SizedBox(
      height: 52,
      child: ListView(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(vertical: 8, horizontal: ThemeSpacing.sp4),
        physics: const BouncingScrollPhysics(),
        children: [
          _FilterChip(
            label: 'All',
            isSelected: activeFilter == null,
            onTap: () {
              ref
                  .read(checkpointStatusFilterProvider.notifier)
                  .setFilter(null);
            },
          ),
          _FilterChip(
            label: 'Active',
            color: ThemeColors.danger,
            isSelected: activeFilter == ContributionStatusEnum.ACTIVE,
            onTap: () {
              ref
                  .read(checkpointStatusFilterProvider.notifier)
                  .setFilter(ContributionStatusEnum.ACTIVE);
            },
          ),
          _FilterChip(
            label: 'Activity',
            color: const Color(0xFFFF9500),
            isSelected: activeFilter == ContributionStatusEnum.POLICE_ALERT,
            onTap: () {
              ref
                  .read(checkpointStatusFilterProvider.notifier)
                  .setFilter(ContributionStatusEnum.POLICE_ALERT);
            },
          ),
          _FilterChip(
            label: 'Inactive',
            color: const Color(0xFF34C759),
            isSelected: activeFilter == ContributionStatusEnum.INACTIVE,
            onTap: () {
              ref
                  .read(checkpointStatusFilterProvider.notifier)
                  .setFilter(ContributionStatusEnum.INACTIVE);
            },
          ),
        ],
      ),
    );
  }
}

class _FilterChip extends StatelessWidget {
  final String label;
  final bool isSelected;
  final VoidCallback onTap;
  final Color? color;

  const _FilterChip({
    required this.label,
    required this.isSelected,
    required this.onTap,
    this.color,
  });

  @override
  Widget build(BuildContext context) {
    final themeColor = color ?? ThemeColors.accent;
    return Padding(
      padding: const EdgeInsets.only(right: 6),
      child: InkWell(
        onTap: onTap,
        borderRadius: ThemeRadius.brFull,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 200),
          padding: const EdgeInsets.symmetric(horizontal: 16),
          decoration: BoxDecoration(
            color:
                isSelected
                    ? themeColor.withValues(alpha: 0.1)
                    : ThemeColors.stone100,
            borderRadius: ThemeRadius.brFull,
            border: Border.all(
              color: isSelected ? themeColor : Colors.transparent,
              width: 1.5,
            ),
          ),
          child: Center(
            child: Text(
              label,
              style: TextStyle(
                fontSize: 13,
                fontWeight: isSelected ? FontWeight.w800 : FontWeight.w600,
                color: isSelected ? themeColor : ThemeColors.textSecondary,
                letterSpacing: -0.2,
              ),
            ),
          ),
        ),
      ),
    );
  }
}

