import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';

class CheckpointEmptyView extends StatelessWidget {
  final String query;
  final ContributionStatusEnum? status;

  const CheckpointEmptyView({required this.query, this.status, super.key});

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    return SliverFillRemaining(
      hasScrollBody: false,
      child: Center(
        child: Padding(
          padding: const EdgeInsets.all(ThemeSpacing.sp10),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Icon(
                CupertinoIcons.square_stack_3d_up_slash,
                size: 48,
                color: ThemeColors.stone300,
              ),
              const SizedBox(height: ThemeSpacing.sp6),
              Text(
                query.isNotEmpty ? 'No matches found' : 'No data here',
