                    label: 'Phone',
                    value: user.profile.phoneNumber ?? 'Not provided',
                    icon: CupertinoIcons.phone,
                    isLast: true,
                  ),
                ],
              ),
              const SizedBox(height: ThemeSpacing.sp8),
              const _SectionHeader(title: 'Subscription'),
              _GroupedSettings(
                children: [
                  _SettingTile(
                    label: 'Manage Billing',
                    icon: CupertinoIcons.creditcard,
                    isLast: true,
                    onTap: () async {
                      final url =
                          await ref
                              .read(profileControllerProvider.notifier)
                              .createPortalSession();
                      if (url != null) {
                        await _launchUrl(url);
                      }
                    },
                  ),
                ],
              ),
              const SizedBox(height: ThemeSpacing.sp8),
              const _SectionHeader(title: 'Support and Legal'),
              _GroupedSettings(
                children: [
                  _SettingTile(
                    label: 'Help and Support',
                    icon: CupertinoIcons.question_circle,
                    onTap:
                        () => unawaited(_launchUrl('https://ukcheckpoints.info/help')),
                  ),
                  _SettingTile(
                    label: 'Privacy Policy',
                    icon: CupertinoIcons.shield,
                    onTap:
                        () => unawaited(_launchUrl(
                          'https://ukcheckpoints.info/privacy',
                        )),
                  ),
                  _SettingTile(
                    label: 'Terms of Service',
                    icon: CupertinoIcons.doc_text,
                    isLast: true,
                    onTap:
                        () => unawaited(_launchUrl(
                          'https://ukcheckpoints.info/terms',
