                onTap: () => ref.read(authControllerProvider.notifier).logout(),
              ),
              const SizedBox(height: ThemeSpacing.sp4),
              _ActionCard(
                label: 'Delete Account',
                icon: CupertinoIcons.trash,
                isDestructive: true,
                onTap: () => _showDeleteConfirmation(context, ref),
