import 'package:ukcheckpoints_app/core/utils/logger.dart';

class ContributionGraph extends StatelessWidget {
  final List<WeeklyContribution> contributions;

  const ContributionGraph({required this.contributions, super.key});

  @override
  Widget build(BuildContext context) {
    if (contributions.isEmpty) return const SizedBox.shrink();

    final maxCount = contributions
        .map((e) => e.count)
        .fold(0.0, (prev, curr) => curr > prev ? curr.toDouble() : prev);

    return Container(
      height: 160,
      padding: const EdgeInsets.all(ThemeSpacing.sp5),
      decoration: BoxDecoration(
        color: ThemeColors.bgRaised,
        borderRadius: ThemeRadius.brLg,
        border: Border.all(color: ThemeColors.border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'Weekly Activity',
            style: TextStyle(
              fontSize: 13,
              fontWeight: FontWeight.w700,
              color: ThemeColors.textPrimary,
            ),
          ),
          const SizedBox(height: ThemeSpacing.sp5),
          Expanded(
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              crossAxisAlignment: CrossAxisAlignment.end,
              children:
                  contributions.reversed.map((c) {
                    final heightFactor =
                        maxCount > 0 ? c.count / maxCount : 0.0;
                    return _Bar(
                      label: _getDayLabel(c.date),
                      heightFactor: heightFactor,
                      count: c.count.toInt(),
                    );
                  }).toList(),
            ),
          ),
        ],
      ),
    );
  }

  String _getDayLabel(String dateStr) {
    try {
      final date = DateTime.parse(dateStr);
      return ['S', 'M', 'T', 'W', 'T', 'F', 'S'][date.weekday % 7];
    } catch (e, st) {
      AppLogger.error('Error parsing date in contribution graph', error: e, stackTrace: st);
      return '';
    }
  }
}

class _Bar extends StatelessWidget {
  final String label;
  final double heightFactor;
  final int count;

  const _Bar({
    required this.label,
    required this.heightFactor,
    required this.count,
  });

  @override
  Widget build(BuildContext context) {
    return Column(
      mainAxisAlignment: MainAxisAlignment.end,
      children: [
        if (count > 0)
          Text(
            count.toString(),
            style: const TextStyle(
              fontSize: 9,
              fontWeight: FontWeight.w700,
              color: ThemeColors.accent,
            ),
          ),
        const SizedBox(height: 4),
        Flexible(
          child: FractionallySizedBox(
            heightFactor: heightFactor.clamp(0.08, 1.0),
            child: Container(
              width: 24,
              decoration: BoxDecoration(
                color: count > 0 ? ThemeColors.accent : ThemeColors.stone200,
                borderRadius: const BorderRadius.vertical(
                  top: Radius.circular(ThemeRadius.rXs),
                ),
              ),
            ),
          ),
        ),
        const SizedBox(height: 8),
        Text(
          label,
          style: const TextStyle(
            fontSize: 10,
            fontWeight: FontWeight.w600,
            color: ThemeColors.textTertiary,
          ),
        ),
      ],
    );
  }
}

