import 'package:riverpod_annotation/riverpod_annotation.dart';
import 'package:ukcheckpoints_api/ukcheckpoints_api.dart';
import 'package:ukcheckpoints_app/core/utils/logger.dart';
import 'package:ukcheckpoints_app/features/auth/providers/auth_controller.dart';
import 'package:ukcheckpoints_app/features/profile/data/profile_repository.dart';
import 'package:ukcheckpoints_app/features/profile/domain/profile_error.dart';

part 'profile_controller.g.dart';

@riverpod
class ProfileController extends _$ProfileController {
  @override
  FutureOr<List<ReferralCodeDto>> build() async {
    final repo = ref.read(profileRepositoryProvider);
    return repo.fetchReferralCodes();
  }

  Future<void> createReferralCode() async {
    state = const AsyncLoading();
    try {
      final repo = ref.read(profileRepositoryProvider);
      await repo.createReferralCode();
      final codes = await repo.fetchReferralCodes();
      state = AsyncData(codes);
    } catch (e, st) {
      AppLogger.error('Profile action failed', error: e, stackTrace: st);
      state = AsyncError(
        const ProfileActionError('Could not create referral code.'),
        st,
      );
    }
  }

  Future<String?> createPortalSession() async {
    try {
      final repo = ref.read(profileRepositoryProvider);
      return await repo.createPortalSession();
    } catch (e, st) {
      AppLogger.error(
        'Failed to fetch customer portal URL',
        error: e,
        stackTrace: st,
      );
      return null;
    }
  }

  Future<void> deleteAccount() async {
    state = const AsyncLoading();
    try {
      final repo = ref.read(profileRepositoryProvider);
      await repo.deleteAccount();
      await ref.read(authControllerProvider.notifier).logout();
    } catch (e, st) {
      AppLogger.error('Profile action failed', error: e, stackTrace: st);
      state = AsyncError(
        const ProfileActionError('Could not delete account.'),
        st,
      );
    }
  }
}

import 'dart:async';

import 'package:flutter/material.dart';
import 'package:ukcheckpoints_app/core/theme/theme.dart';

class ProfileShimmer extends StatefulWidget {
  const ProfileShimmer({super.key});

  @override
  State<ProfileShimmer> createState() => _ProfileShimmerState();
}

class _ProfileShimmerState extends State<ProfileShimmer>
    with SingleTickerProviderStateMixin {
  late AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 1500),
    );
    unawaited(_controller.repeat());
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return AnimatedBuilder(
      animation: _controller,
      builder: (context, child) {
        return SingleChildScrollView(
          padding: const EdgeInsets.all(ThemeSpacing.sp4),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  _ShimmerBox(width: 80, height: 80, controller: _controller),
                  const SizedBox(width: ThemeSpacing.sp5),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      _ShimmerBox(
                        width: 140,
                        height: 20,
                        controller: _controller,
                      ),
                      const SizedBox(height: 8),
                      _ShimmerBox(
                        width: 100,
                        height: 14,
                        controller: _controller,
                      ),
                    ],
                  ),
                ],
              ),
              const SizedBox(height: ThemeSpacing.sp8),
              _ShimmerBox(
                width: double.infinity,
                height: 100,
                controller: _controller,
              ),
              const SizedBox(height: ThemeSpacing.sp8),
              _ShimmerBox(
                width: double.infinity,
                height: 80,
                controller: _controller,
              ),
              const SizedBox(height: ThemeSpacing.sp8),
              _ShimmerBox(width: 120, height: 16, controller: _controller),
              const SizedBox(height: ThemeSpacing.sp4),
              _ShimmerBox(
                width: double.infinity,
                height: 60,
                controller: _controller,
              ),
              const SizedBox(height: ThemeSpacing.sp3),
              _ShimmerBox(
                width: double.infinity,
                height: 60,
                controller: _controller,
              ),
            ],
          ),
        );
      },
    );
  }
}

class _ShimmerBox extends StatelessWidget {
  final double width;
  final double height;
  final AnimationController controller;

  const _ShimmerBox({
    required this.width,
    required this.height,
    required this.controller,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      width: width,
      height: height,
      decoration: BoxDecoration(
        color: ThemeColors.stone200,
        borderRadius: ThemeRadius.brMd,
      ),
      child: ClipRRect(
        borderRadius: ThemeRadius.brMd,
        child: FractionallySizedBox(
          widthFactor: 2,
          child: Transform.translate(
            offset: Offset(-width + (width * 2 * controller.value), 0),
            child: Container(
              decoration: const BoxDecoration(
                gradient: LinearGradient(
                  colors: [
                    ThemeColors.stone200,
                    ThemeColors.stone100,
                    ThemeColors.stone200,
                  ],
                  stops: [0.3, 0.5, 0.7],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

