import 'package:dio/dio.dart';
import 'package:riverpod_annotation/riverpod_annotation.dart';

import 'package:ukcheckpoints_app/core/utils/logger.dart';
import 'package:ukcheckpoints_app/features/auth/data/auth_repository.dart';
import 'package:ukcheckpoints_app/features/auth/domain/auth_error.dart';
import 'package:ukcheckpoints_app/features/auth/domain/auth_user.dart';

part 'auth_controller.g.dart';

@riverpod
class AuthController extends _$AuthController {
  @override
  FutureOr<AuthUser?> build() async {
    final repo = ref.read(authRepositoryProvider);
    final result = await repo.restoreSession();

    if (result.error != null) {
      throw result.error!;
    }

    return result.user;
  }

  void clearError() {
    if (state.hasError) {
      state = AsyncData(state.valueOrNull);
    }
  }

